69	func TestEvaluateRulePriorityFalseWinsAndIsImmediate(t *testing.T) {
70		// 已启用的开关，default=true：r-deny 在前、返回 false，含一个 eq 与一个 in
71		// 条件（AND）；r-allow 在后、返回 true，且两条规则可以同时成立。
72		// 公开规则：按数组顺序，第一条所有条件都成立的规则立即定案——即使它返回
73		// false，也不能被后面的 true 规则或 true 默认值翻转。
74		rDenyFirst := `{"flags":[{"key":"f","enabled":true,"default":true,"rules":[
75			{"id":"r-deny","value":false,"conditions":[
76				{"attribute":"plan","op":"eq","value":"pro"},
77				{"attribute":"tier","op":"in","value":["a","b"]}]},
78			{"id":"r-allow","value":true,"conditions":[
79				{"attribute":"region","op":"eq","value":"cn"}]}]}]}`
80		denyID, allowID := "r-deny", "r-allow"
81	
82		// 上下文同时满足两条规则：前面的 r-deny 获胜，结果为 false；reason=rule、
83		// ruleId 指向前一条，与后面的规则及默认值同为 true 无关。
84		got := eval(t, rDenyFirst, "f", `{"plan":"pro","tier":"a","region":"cn"}`)
85		want := EvalResult{Key: "f", Value: false, Reason: EvalRule, RuleID: &denyID}
86		if !got.Equals(want) {
87			t.Fatalf("both match, earlier false must decide: got %+v, want %+v", got, want)
88		}
89	
90		// 只交换两条规则的配置位置，规则内容与上下文完全相同：改由原来的后一条
91		// r-allow 返回 true，命中原因与规则编号跟随获胜规则变化。
92		rAllowFirst := `{"flags":[{"key":"f","enabled":true,"default":true,"rules":[
93			{"id":"r-allow","value":true,"conditions":[
94				{"attribute":"region","op":"eq","value":"cn"}]},
95			{"id":"r-deny","value":false,"conditions":[
96				{"attribute":"plan","op":"eq","value":"pro"},
97				{"attribute":"tier","op":"in","value":["a","b"]}]}]}]}`
98		got = eval(t, rAllowFirst, "f", `{"plan":"pro","tier":"a","region":"cn"}`)
99		want = EvalResult{Key: "f", Value: true, Reason: EvalRule, RuleID: &allowID}
100		if !got.Equals(want) {
101			t.Fatalf("swap order, earlier true must decide: got %+v, want %+v", got, want)
102		}
103	
104		// 前面的规则只有部分条件成立（eq 成立但 in 不成立）：任何单个条件成立都
105		// 不算命中，也不能因前一条返回 false 就停止；完整成立的后一条 r-allow 获胜。
106		got = eval(t, rDenyFirst, "f", `{"plan":"pro","tier":"c","region":"cn"}`)
107		want = EvalResult{Key: "f", Value: true, Reason: EvalRule, RuleID: &allowID}
108		if !got.Equals(want) {
109			t.Fatalf("partial match must fall through: got %+v, want %+v", got, want)
110		}
111		// 前一条的 eq 属性缺失（而非不等）：同样只是不命中，继续检查后一条。
112		got = eval(t, rDenyFirst, "f", `{"tier":"a","region":"cn"}`)
113		if !got.Equals(want) {
114			t.Fatalf("missing attr on earlier rule must fall through: got %+v, want %+v", got, want)
115		}
116	
117		// 两条规则都不成立：采用 default=true，reason=default、ruleId=null，
118		// 与“某条规则返回 true”的命中（reason=rule 且带 ruleId）明确区分。
119		got = eval(t, rDenyFirst, "f", `{"plan":"free","tier":"c","region":"eu"}`)
120		want = EvalResult{Key: "f", Value: true, Reason: EvalDefault, RuleID: nil}
121		if !got.Equals(want) {
122			t.Fatalf("neither matches must use default: got %+v, want %+v", got, want)
123		}
124	}
