180	func TestEqSemantics(t *testing.T) {
181		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
182			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"Pro"}]}]}]}`
183		cases := map[string]string{
184			`{"plan":"Pro"}`:  "match",
185			`{"plan":"pro"}`:  "case",       // 区分大小写
186			`{"plan":" Pro"}`: "whitespace", // 不裁剪空白
187			`{}`:              "missing",
188		}
189		for ctxRaw, label := range cases {
190			got := eval(t, cfg, "f", ctxRaw)
191			matched := got.Reason == EvalRule
192			wantMatch := label == "match"
193			if matched != wantMatch {
194				t.Errorf("%s (%s): match=%v want %v", label, ctxRaw, matched, wantMatch)
195			}
196		}
197	
198		// 空字符串是合法属性值，可以被 eq 命中。
199		cfgEmpty := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
200			{"id":"r1","value":true,"conditions":[{"attribute":"note","op":"eq","value":""}]}]}]}`
201		got := eval(t, cfgEmpty, "f", `{"note":""}`)
202		if got.Reason != EvalRule || !got.Value {
203			t.Fatalf("empty string eq: got %+v", got)
204		}
