212	func TestInSemantics(t *testing.T) {
213		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
214			{"id":"r1","value":true,"conditions":[{"attribute":"tier","op":"in","value":["a","b",""]}]}]}]}`
215		hit := eval(t, cfg, "f", `{"tier":"a"}`)
216		if hit.Reason != EvalRule {
