1161		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
1162			{"id":"r-exp","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"1e400"}]},
1163			{"id":"r-neg","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"-1e400"}]},
1164			{"id":"r-int","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"` + hugeInt + `"}]}]}]}`
1165		for _, tc := range []struct {
1166			ctxRaw string
1167			ruleID string
1168			reason EvalReason
1169		}{
1170			{`{"plan":"1e400"}`, "r-exp", EvalRule},
1171			{`{"plan":"-1e400"}`, "r-neg", EvalRule},
1172			{`{"plan":"` + hugeInt + `"}`, "r-int", EvalRule},
1173			{`{"plan":"1e401"}`, "", EvalDefault}, // 不做数值换算："1e401" != "1e400"
1174		} {
1175			got := eval(t, cfg, "f", tc.ctxRaw)
1176			if got.Reason != tc.reason ||
1177				(tc.reason == EvalRule && (got.RuleID == nil || *got.RuleID != tc.ruleID)) {
