1186			t.Fatalf("numerically equal spellings must not match as strings: %+v", got)
1187		}
1188		if got := eval(t, cfgInt, "g", `{"plan":"`+hugeInt+`"}`); got.Reason != EvalRule {
1189			t.Fatalf("identical spelling must match verbatim: %+v", got)
1190		}
