1129	// --- evaluate 对 in 条件精确成员判断的端到端回归保障 ---------------------------
1130	//
1131	// 下列常量用 Go 原始字符串拼接出 JSON 转义文本（与本文件既有写法一致），确保
1132	// “转义写法”和“直接字符”在源码层面就是两个不同的输入。
1133	const (
1134		// cliEscEA 是 U+00E9 的 JSON 转义写法；cliEscCB 是 e 加组合附加符号 U+0301
1135		// 的转义写法（与预组合字符不同）；cliEscGR 是 U+1F600 的一对代理项转义；
1136		// cliEscTier 是属性名 tier 四个字母各自转义后的写法。
1137		cliEscEA   = (`\u` + `00E9`)
1138		cliEscCB   = (`e\u` + `0301`)
1139		cliEscGR   = (`\u` + `D83D`) + (`\u` + `DE00`)
1140		cliEscTier = (`\u` + `0074`) + (`\u` + `0069`) + (`\u` + `0065`) + (`\u` + `0072`)
1141		// cliLitEA 是 JSON 里“已转义的反斜杠后接 u00E9”的普通文本（两个反斜杠
1142		// 后接 u00E9），解码后只是六个字面字符，不再是 Unicode 转义。
1143		cliLitEA = (`\` + `\` + `u00E9`)
1144	)
1145	
1146	// cliInListConfig 拼出只有一个启用开关、一条 in 规则（id=r1、value=true、
1147	// default=false）的配置；listJSON 是完整的候选值数组文本。
1148	func cliInListConfig(listJSON string) string {
1149		return `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[` +
1150			`{"id":"r1","value":true,"conditions":[` +
1151			`{"attribute":"tier","op":"in","value":` + listJSON + `}]}]}]}`
1152	}
1153	
1154	// TestCLIEvaluateInDecodedSpellingEquivalence 端到端验证：同一属性名、列表
1155	// 候选值或上下文值，无论用直接字符还是合法 Unicode 转义（含代理项对）书写，
1156	// evaluate 都输出逐字节一致的单个 JSON 对象（key、value、reason、ruleId
1157	// 完全一致）；配置与上下文可分别使用不同写法。
1158	func TestCLIEvaluateInDecodedSpellingEquivalence(t *testing.T) {
1159		configs := []struct {
1160			name string
1161			raw  string
1162		}{
1163			{"direct", cliInListConfig(`["é","😀","other"]`)},
1164			{"escaped", cliInListConfig(`["` + cliEscEA + `","` + cliEscGR + `","other"]`)},
1165			{"mixed", cliInListConfig(`["é","` + cliEscGR + `","other"]`)},
1166		}
1167		contexts := []struct {
1168			name string
1169			raw  string
1170		}{
1171			{"e-acute direct", `{"tier":"é"}`},
1172			{"e-acute escaped", `{"tier":"` + cliEscEA + `"}`},
1173			{"emoji direct", `{"tier":"😀"}`},
1174			{"emoji surrogate pair", `{"tier":"` + cliEscGR + `"}`},
1175			{"plain ascii", `{"tier":"other"}`},
1176		}
1177		var reference string
1178		for ci, cfg := range configs {
1179			for _, cx := range contexts {
1180				t.Run(cfg.name+"/"+cx.name, func(t *testing.T) {
1181					h := newHarness(t, cfg.raw, cx.raw)
