1453	// explainSuccess 运行带 --explain 的 evaluate 并把 stdout 解码为单个对象。
1454	func explainSuccess(t *testing.T, h *harness, key string) map[string]any {
1455		t.Helper()
1456		var stdout, stderr bytes.Buffer
1457		if code := run(h.evalExplainArgs(key), &stdout, &stderr); code != 0 {
1458			t.Fatalf("exit=%d stderr=%s", code, stderr.String())
1459		}
1460		if stderr.Len() != 0 {
1461			t.Fatalf("stderr must be empty on success: %q", stderr.String())
1462		}
1463		out := stdout.String()
1464		if strings.Count(strings.TrimSpace(out), "\n") != 0 {
1465			t.Fatalf("stdout must contain exactly one JSON object line: %q", out)
1466		}
1467		var got map[string]any
1468		if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
1469			t.Fatalf("stdout is not a single JSON object: %q (%v)", out, err)
1470		}
1471		return got
1472	}
