package payflow

import "testing"

func makeBigListFlag(n int) (*Flag, *Context) {
	items := make([]any, n)
	for i := range items {
		items[i] = "candidate-value-that-is-fairly-long"
	}
	// 手工构造一个含超大 in 列表的合法开关（不经 JSON 文本以保持测试轻量）。
	cond := Condition{Attribute: "tier", Op: "in", inVal: make([]string, n)}
	for i := range items {
		cond.inVal[i] = items[i].(string)
	}
	flag := &Flag{Key: "f", Enabled: true, Default: false, Rules: []Rule{
		{ID: "r1", Value: true, Conditions: []Condition{cond}},
	}}
	ctx := &Context{values: map[string]string{"tier": "not-a-member"}}
	return flag, ctx
}

func BenchmarkPlainBigList(b *testing.B) {
	for _, n := range []int{16, 16000} {
		flag, ctx := makeBigListFlag(n)
		b.Run("plain-N", func(b *testing.B) {
			allocs := testing.AllocsPerRun(b.N, func() {
				if r := flag.Evaluate(ctx); r.Reason != EvalDefault {
					b.Fatalf("want default, got %v", r)
				}
			})
			b.ReportMetric(float64(allocs), "allocs/op")
		})
	}
	for _, n := range []int{16, 16000} {
		flag, ctx := makeBigListFlag(n)
		b.Run("explain-N", func(b *testing.B) {
			allocs := testing.AllocsPerRun(b.N, func() {
				if r := flag.EvaluateExplain(ctx); r.Reason != EvalDefault {
					b.Fatalf("want default, got %v", r)
				}
			})
			b.ReportMetric(float64(allocs), "allocs/op")
		})
	}
}

